#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
Sistema Unificado de Invernadero
- Selector inicial: Lógica Difusa Mamdani / Sistema Experto Fitosanitario
- Cada sistema conserva su funcionamiento original.
- El botón Reiniciar / volver al inicio regresa al selector y crea una nueva
  instancia del sistema para poder ingresar datos nuevos.
"""

import tkinter as tk
from tkinter import ttk, messagebox
from pathlib import Path


def _cargar_modulos():
    """Carga los dos programas originales en espacios separados para evitar
    conflictos entre sus variables y estilos globales."""
    fuzzy_ns = {"__name__": "invernadero_fuzzy", "__file__": str(Path(__file__).resolve())}
    expert_ns = {"__name__": "invernadero_experto", "__file__": str(Path(__file__).resolve())}
    exec(FUZZY_SOURCE, fuzzy_ns)
    exec(EXPERT_SOURCE, expert_ns)
    return fuzzy_ns, expert_ns


def iniciar_aplicacion():
    fuzzy_ns, expert_ns = _cargar_modulos()
    FuzzyApp = fuzzy_ns["InvernaderoSkfuzzyApp"]
    ExpertApp = expert_ns["InvernaderoGUI"]

    root = tk.Tk()
    root.title("Sistema Experto de Invernadero")
    root.geometry("760x520")
    root.minsize(650, 450)
    root.configure(bg="#F3F6F3")

    current_app = {"instance": None}

    style = ttk.Style(root)
    if "clam" in style.theme_names():
        style.theme_use("clam")
    style.configure("App.TFrame", background="#F3F6F3")
    style.configure("Header.TFrame", background="#1F6D3D")
    style.configure("Card.TFrame", background="#FFFFFF")
    style.configure("Header.TLabel", background="#1F6D3D", foreground="#FFFFFF",
                    font=("Segoe UI", 21, "bold"))
    style.configure("Sub.TLabel", background="#1F6D3D", foreground="#DDEFE2",
                    font=("Segoe UI", 10))
    style.configure("Title.TLabel", background="#FFFFFF", foreground="#164F2C",
                    font=("Segoe UI", 15, "bold"))
    style.configure("Desc.TLabel", background="#FFFFFF", foreground="#5B6B60",
                    font=("Segoe UI", 10), wraplength=580, justify="center")
    style.configure("Select.TButton", background="#1F6D3D", foreground="#FFFFFF",
                    font=("Segoe UI", 12, "bold"), padding=(18, 12))
    style.map("Select.TButton", background=[("active", "#164F2C")])
    style.configure("Exit.TButton", padding=(12, 8))

    def limpiar_ventana():
        plt = fuzzy_ns.get("plt")
        if plt is not None:
            try:
                plt.close("all")
            except Exception:
                pass
        for widget in root.winfo_children():
            widget.destroy()
        current_app["instance"] = None

    def mostrar_selector():
        limpiar_ventana()
        root.title("Sistema Experto de Invernadero")
        root.geometry("760x520")

        header = ttk.Frame(root, style="Header.TFrame", padding=(28, 24))
        header.pack(fill="x")
        ttk.Label(header, text="🌱 Sistema Experto de Invernadero",
                  style="Header.TLabel").pack(anchor="center")
        ttk.Label(header, text="Seleccione el sistema que desea utilizar",
                  style="Sub.TLabel").pack(anchor="center", pady=(6, 0))

        body = ttk.Frame(root, style="App.TFrame", padding=(35, 30))
        body.pack(fill="both", expand=True)

        card = tk.Frame(body, bg="#FFFFFF", highlightbackground="#DCE5DD",
                        highlightthickness=1)
        card.pack(fill="both", expand=True)
        inner = ttk.Frame(card, style="Card.TFrame", padding=(35, 28))
        inner.pack(fill="both", expand=True)

        ttk.Label(inner, text="¿Qué sistema desea abrir?",
                  style="Title.TLabel").pack(pady=(0, 8))
        ttk.Label(inner,
                  text="Puede volver a esta pantalla en cualquier momento usando el botón de reinicio. "
                       "Al abrir nuevamente un sistema se crea una sesión nueva para ingresar datos nuevos.",
                  style="Desc.TLabel").pack(pady=(0, 24))

        ttk.Button(inner, text="💧  Lógica Difusa Mamdani\n   Temperatura + humedad → tiempo de riego",
                   style="Select.TButton", command=mostrar_fuzzy).pack(fill="x", pady=7)
        ttk.Button(inner, text="🔬  Sistema Experto Fitosanitario\n   Diagnóstico de plagas y enfermedades",
                   style="Select.TButton", command=mostrar_experto).pack(fill="x", pady=7)
        ttk.Button(inner, text="Salir", style="Exit.TButton", command=root.destroy).pack(pady=(18, 0))

    def mostrar_fuzzy():
        limpiar_ventana()
        root.title("Invernadero · Lógica Difusa Mamdani")
        try:
            current_app["instance"] = FuzzyApp(root, on_back=mostrar_selector)
        except Exception as err:
            limpiar_ventana()
            messagebox.showerror(
                "No se pudo abrir Lógica Difusa",
                f"No fue posible iniciar el sistema difuso.\n\n{err}\n\n"
                "Instala las dependencias con:\n"
                "pip install scipy numpy matplotlib networkx scikit-fuzzy",
            )
            mostrar_selector()

    def mostrar_experto():
        limpiar_ventana()
        root.title("Invernadero · Sistema Experto Fitosanitario")
        try:
            current_app["instance"] = ExpertApp(root, on_back=mostrar_selector)
        except Exception as err:
            limpiar_ventana()
            messagebox.showerror(
                "No se pudo abrir Sistema Experto",
                f"No fue posible iniciar el sistema experto.\n\n{err}\n\n"
                "Instala la dependencia con:\n"
                "pip install clipspy",
            )
            mostrar_selector()

    mostrar_selector()
    root.mainloop()


FUZZY_SOURCE = '#!/usr/bin/env python3\n# -*- coding: utf-8 -*-\n"""\n==============================================================================\n Sistema de Lógica Difusa con scikit-fuzzy (skfuzzy) + interfaz Tkinter\n Tema: Invernadero inteligente — Control automático de tiempo de riego\n==============================================================================\n"""\n\nimport sys\ntry:\n    import numpy as np\nexcept ImportError:\n    np = None\n\nimport tkinter as tk\nfrom tkinter import ttk, messagebox\nfrom pathlib import Path\n\ntry:\n    import matplotlib\n    matplotlib.use("TkAgg")\n    import matplotlib.pyplot as plt\n    from matplotlib.backends.backend_tkagg import FigureCanvasTkAgg\nexcept ImportError as _err:\n    matplotlib = None\n    plt = None\n    FigureCanvasTkAgg = None\n    MATPLOTLIB_IMPORT_ERROR = _err\n\ntry:\n    import skfuzzy as fuzz\n    from skfuzzy import control as ctrl\nexcept ImportError as _err:\n    fuzz = None\n    ctrl = None\n    SKFUZZY_IMPORT_ERROR = _err\n\n\n# ==============================================================================\n# [1] PARÁMETROS DE LAS ETIQUETAS (a,b,c,d) - LÓGICA MEJORADA\n# ==============================================================================\n# Se ajustan para tener sentido agronómico en un invernadero\nTEMP_PARAMS = {\n    "Fria": (0, 0, 15, 20),\n    "Optima": (15, 20, 25, 30),\n    "Calor": (25, 30, 40, 40),\n}\nHUM_PARAMS = {\n    "Seca": (0, 0, 20, 40),\n    "Ideal": (30, 50, 60, 75),\n    "Exceso": (65, 80, 100, 100),\n}\nRIEGO_PARAMS = {\n    "Nada": (0, 0, 0, 5),          # Riego de 0 a 5 min (tendencia a 0)\n    "Moderado": (3, 10, 15, 22),   # Riego medio\n    "Abundante": (18, 25, 30, 30), # Riego largo para combatir sequía severa\n}\n\n# Descripciones para la interfaz visual\nDESCRIPCION_REGLAS = [\n    "R1: SI humedad es Exceso  ➔  riego Nada (evita ahogamiento).",\n    "R2: SI humedad es Ideal   ➔  riego Moderado (mantenimiento).",\n    "R3: SI humedad es Seca Y temperatura Calor  ➔  riego Abundante.",\n    "R4: SI humedad es Seca Y temperatura (Fría o Óptima)  ➔  riego Moderado.",\n]\n\n\n# ==============================================================================\n# [2] NÚCLEO DIFUSO (skfuzzy)\n# ==============================================================================\ndef construir_sistema():\n    if np is None:\n        raise ImportError("Falta NumPy. Instálalo con: pip install numpy")\n    if plt is None:\n        raise ImportError("Falta Matplotlib. Instálalo con: pip install matplotlib")\n    if fuzz is None or ctrl is None:\n        raise ImportError("Falta scikit-fuzzy o alguna dependencia. Instálalo con: pip install scipy numpy matplotlib networkx scikit-fuzzy")\n\n    temperatura = ctrl.Antecedent(np.arange(0, 40.01, 0.1), "temperatura")\n    humedad = ctrl.Antecedent(np.arange(0, 100.01, 0.1), "humedad_suelo")\n    riego = ctrl.Consequent(np.arange(0, 30.01, 0.1), "tiempo_riego")\n\n    # Inyección de las funciones de pertenencia trapezoidales\n    for nombre, params in TEMP_PARAMS.items():\n        temperatura[nombre.lower()] = fuzz.trapmf(temperatura.universe, list(params))\n    for nombre, params in HUM_PARAMS.items():\n        humedad[nombre.lower()] = fuzz.trapmf(humedad.universe, list(params))\n    for nombre, params in RIEGO_PARAMS.items():\n        riego[nombre.lower()] = fuzz.trapmf(riego.universe, list(params))\n\n    # Creación de las reglas matemáticas\n    regla1 = ctrl.Rule(humedad["exceso"], riego["nada"])\n    regla2 = ctrl.Rule(humedad["ideal"], riego["moderado"])\n    regla3 = ctrl.Rule(humedad["seca"] & temperatura["calor"], riego["abundante"])\n    # skfuzzy permite usar el operador OR (|) internamente para agrupar antecedentes\n    regla4 = ctrl.Rule(humedad["seca"] & (temperatura["fria"] | temperatura["optima"]), riego["moderado"])\n\n    sistema_ctrl = ctrl.ControlSystem([regla1, regla2, regla3, regla4])\n    simulacion = ctrl.ControlSystemSimulation(sistema_ctrl)\n    return temperatura, humedad, riego, simulacion\n\n\ndef describir_rango(a, b, c, d):\n    if a == b == c == d:\n        return f"Solo en {a}"\n    if a == b and c == d:\n        return f"100% segura entre {a} y {d} (escalón)"\n    if a == b:\n        return f"100% segura hasta {c}; luego baja gradualmente hasta {d}"\n    if c == d:\n        return f"Sube gradualmente desde {a}; 100% segura desde {b}"\n    return f"Sube de {a} a {b}; 100% segura de {b} a {c}; baja de {c} a {d}"\n\n\n# ==============================================================================\n# [3] PALETA / ESTILO (Diseño UI)\n# ==============================================================================\nCOLOR_BG = "#F3F6F3"\nCOLOR_PANEL = "#FFFFFF"\nCOLOR_PRIMARY = "#1F6D3D"\nCOLOR_PRIMARY_DARK = "#164F2C"\nCOLOR_TEXT = "#1E2A22"\nCOLOR_MUTED = "#5B6B60"\nCOLOR_BORDER = "#DCE5DD"\nFONT_FAMILY = "Segoe UI"\n\n\n# ==============================================================================\n# [4] APLICACIÓN TKINTER\n# ==============================================================================\nclass InvernaderoSkfuzzyApp:\n    def __init__(self, root, on_back=None):\n        self.root = root\n        self.on_back = on_back\n        self.root.title("Invernadero difuso · scikit-fuzzy")\n        self.root.geometry("1000x1040")\n        self.root.minsize(880, 800)\n        self.root.configure(bg=COLOR_BG)\n\n        self.temperatura, self.humedad, self.riego, self.sim = construir_sistema()\n        self.carpeta_script = Path(__file__).resolve().parent\n\n        self._configurar_estilos()\n        self._construir_layout()\n\n    def _configurar_estilos(self):\n        style = ttk.Style(self.root)\n        if "clam" in style.theme_names():\n            style.theme_use("clam")\n\n        style.configure("App.TFrame", background=COLOR_BG)\n        style.configure("Header.TFrame", background=COLOR_PRIMARY)\n        style.configure("Card.TFrame", background=COLOR_PANEL)\n        style.configure("Header.TLabel", background=COLOR_PRIMARY, foreground="#FFFFFF",\n                         font=(FONT_FAMILY, 16, "bold"))\n        style.configure("SubHeader.TLabel", background=COLOR_PRIMARY, foreground="#DDEFE2",\n                         font=(FONT_FAMILY, 10))\n        style.configure("SectionTitle.TLabel", background=COLOR_PANEL, foreground=COLOR_PRIMARY_DARK,\n                         font=(FONT_FAMILY, 12, "bold"))\n        style.configure("FieldLabel.TLabel", background=COLOR_PANEL, foreground=COLOR_TEXT,\n                         font=(FONT_FAMILY, 10))\n        style.configure("Hint.TLabel", background=COLOR_PANEL, foreground=COLOR_MUTED,\n                         font=(FONT_FAMILY, 8, "italic"))\n        style.configure("Resultado.TLabel", background=COLOR_PANEL, foreground=COLOR_PRIMARY_DARK,\n                         font=(FONT_FAMILY, 14, "bold"))\n        style.configure("Status.TLabel", background=COLOR_BG, foreground=COLOR_MUTED,\n                         font=(FONT_FAMILY, 9))\n        style.configure("Accent.TButton", background=COLOR_PRIMARY, foreground="#FFFFFF",\n                         font=(FONT_FAMILY, 11, "bold"), padding=(16, 9))\n        style.map("Accent.TButton", background=[("active", COLOR_PRIMARY_DARK)])\n        style.configure("Secondary.TButton", padding=(10, 6))\n        style.configure("Treeview", rowheight=24, font=(FONT_FAMILY, 9))\n        style.configure("Treeview.Heading", font=(FONT_FAMILY, 9, "bold"))\n\n    def _construir_layout(self):\n        header = ttk.Frame(self.root, style="Header.TFrame", padding=(24, 16))\n        header.pack(fill="x")\n        ttk.Label(header, text="🌱 Sistema Experto de Invernadero — Lógica Difusa Mamdani",\n                  style="Header.TLabel").pack(anchor="w")\n        ttk.Label(header, text="Temperatura + Humedad del suelo  →  Tiempo de riego",\n                  style="SubHeader.TLabel").pack(anchor="w", pady=(4, 0))\n\n        footer = ttk.Frame(self.root, style="App.TFrame", padding=(16, 4, 16, 10))\n        footer.pack(side="bottom", fill="x")\n        self.lbl_estado = ttk.Label(footer, text="Ingresa temperatura y humedad, y presiona calcular.",\n                                     style="Status.TLabel")\n        self.lbl_estado.pack(anchor="w")\n\n        # ---- Lógica de adaptabilidad del Scroll solucionada ----\n        canvas = tk.Canvas(self.root, bg=COLOR_BG, highlightthickness=0)\n        scrollbar = ttk.Scrollbar(self.root, orient="vertical", command=canvas.yview)\n        scroll_frame = ttk.Frame(canvas, style="App.TFrame")\n        \n        scroll_frame.bind("<Configure>", lambda e: canvas.configure(scrollregion=canvas.bbox("all")))\n        frame_id = canvas.create_window((0, 0), window=scroll_frame, anchor="nw")\n        canvas.bind("<Configure>", lambda e: canvas.itemconfig(frame_id, width=e.width))\n\n        canvas.configure(yscrollcommand=scrollbar.set)\n        canvas.pack(side="left", fill="both", expand=True)\n        scrollbar.pack(side="right", fill="y")\n\n        def _rueda(event):\n            canvas.yview_scroll(int(-1 * (event.delta / 120)), "units")\n        canvas.bind("<MouseWheel>", _rueda)\n\n        body = ttk.Frame(scroll_frame, style="App.TFrame", padding=(16, 14, 16, 4))\n        body.pack(fill="both", expand=True)\n        body.columnconfigure(0, weight=1)\n\n        self._construir_tarjeta_rangos(body)\n\n        card_reglas = tk.Frame(body, bg=COLOR_PANEL, highlightbackground=COLOR_BORDER, highlightthickness=1)\n        card_reglas.grid(row=1, column=0, sticky="ew", pady=(0, 10))\n        inner_r = ttk.Frame(card_reglas, style="Card.TFrame", padding=(16, 10))\n        inner_r.pack(fill="x")\n        ttk.Label(inner_r, text="Reglas del sistema", style="SectionTitle.TLabel").pack(anchor="w")\n        for r in DESCRIPCION_REGLAS:\n            ttk.Label(inner_r, text=r, style="FieldLabel.TLabel").pack(anchor="w", pady=(2, 0))\n\n        card_in = tk.Frame(body, bg=COLOR_PANEL, highlightbackground=COLOR_BORDER, highlightthickness=1)\n        card_in.grid(row=2, column=0, sticky="ew", pady=(0, 10))\n        inner_in = ttk.Frame(card_in, style="Card.TFrame", padding=(16, 12))\n        inner_in.pack(fill="x")\n\n        ttk.Label(inner_in, text="Valores nítidos a evaluar", style="SectionTitle.TLabel").grid(\n            row=0, column=0, columnspan=4, sticky="w", pady=(0, 8)\n        )\n\n        ttk.Label(inner_in, text="Temperatura (0-40 °C)", style="FieldLabel.TLabel").grid(row=1, column=0, sticky="w")\n        self.var_temp = tk.StringVar(value="32")\n        ttk.Entry(inner_in, textvariable=self.var_temp, width=10).grid(row=1, column=1, sticky="w", padx=(6, 30))\n\n        ttk.Label(inner_in, text="Humedad suelo (0-100 %)", style="FieldLabel.TLabel").grid(row=1, column=2, sticky="w")\n        self.var_hum = tk.StringVar(value="25")\n        ttk.Entry(inner_in, textvariable=self.var_hum, width=10).grid(row=1, column=3, sticky="w", padx=(6, 0))\n\n        botones = ttk.Frame(inner_in, style="Card.TFrame")\n        botones.grid(row=2, column=0, columnspan=4, sticky="w", pady=(12, 0))\n        ttk.Button(botones, text="🔬 Calcular Inferencia", style="Accent.TButton",\n                   command=self.calcular).pack(side="left")\n        ttk.Button(botones, text="💾 Guardar gráficas (PNG)", style="Secondary.TButton",\n                   command=self.guardar_graficas).pack(side="left", padx=(10, 0))\n        ttk.Button(botones, text="🔄 Reiniciar / volver al inicio", style="Secondary.TButton",\n                   command=self.on_back).pack(side="left", padx=(10, 0))\n\n        self.lbl_resultado = ttk.Label(inner_in, text="Tiempo de riego: —", style="Resultado.TLabel")\n        self.lbl_resultado.grid(row=3, column=0, columnspan=4, sticky="w", pady=(12, 0))\n\n        card_graf = tk.Frame(body, bg=COLOR_PANEL, highlightbackground=COLOR_BORDER, highlightthickness=1)\n        card_graf.grid(row=3, column=0, sticky="nsew")\n        inner_g = ttk.Frame(card_graf, style="Card.TFrame", padding=(10, 10))\n        inner_g.pack(fill="both", expand=True)\n        inner_g.columnconfigure(0, weight=1)\n\n        self.frame_temp = tk.Frame(inner_g, bg=COLOR_PANEL, height=260)\n        self.frame_temp.grid(row=0, column=0, sticky="nsew", pady=2)\n        self.frame_hum = tk.Frame(inner_g, bg=COLOR_PANEL, height=260)\n        self.frame_hum.grid(row=1, column=0, sticky="nsew", pady=2)\n        self.frame_riego = tk.Frame(inner_g, bg=COLOR_PANEL, height=260)\n        self.frame_riego.grid(row=2, column=0, sticky="nsew", pady=2)\n\n        for frame, texto in (\n            (self.frame_temp, "Presiona «Calcular» para ver la gráfica de Temperatura"),\n            (self.frame_hum, "Presiona «Calcular» para ver la gráfica de Humedad"),\n            (self.frame_riego, "Presiona «Calcular» para ver la gráfica de Riego"),\n        ):\n            frame.pack_propagate(False)\n            tk.Label(frame, text=texto, bg=COLOR_PANEL, fg=COLOR_MUTED,\n                     font=(FONT_FAMILY, 9, "italic")).pack(expand=True)\n\n    def _construir_tarjeta_rangos(self, parent):\n        card = tk.Frame(parent, bg=COLOR_PANEL, highlightbackground=COLOR_BORDER, highlightthickness=1)\n        card.grid(row=0, column=0, sticky="ew", pady=(0, 10))\n        inner = ttk.Frame(card, style="Card.TFrame", padding=(16, 12))\n        inner.pack(fill="both", expand=True)\n        inner.columnconfigure(0, weight=1)\n        inner.columnconfigure(1, weight=1)\n\n        ttk.Label(inner, text="ℹ️  Rangos de cada etiqueta (funciones de pertenencia)",\n                  style="SectionTitle.TLabel").grid(row=0, column=0, columnspan=2, sticky="w")\n        ttk.Label(\n            inner,\n            text="Fuera del \\"rango completo\\" la etiqueta vale 0%. Entre el rango completo y el "\n                 "\\"100% segura\\" el valor sube o baja poco a poco (transición).",\n            style="Hint.TLabel", wraplength=900, justify="left",\n        ).grid(row=1, column=0, columnspan=2, sticky="w", pady=(2, 10))\n\n        col_temp = ttk.Frame(inner, style="Card.TFrame")\n        col_temp.grid(row=2, column=0, sticky="nsew", padx=(0, 8))\n        ttk.Label(col_temp, text="🌡️ Temperatura (°C)", style="FieldLabel.TLabel").pack(anchor="w", pady=(0, 4))\n        self._crear_tabla_rangos(col_temp, TEMP_PARAMS)\n\n        col_hum = ttk.Frame(inner, style="Card.TFrame")\n        col_hum.grid(row=2, column=1, sticky="nsew", padx=(8, 0))\n        ttk.Label(col_hum, text="💧 Humedad del suelo (%)", style="FieldLabel.TLabel").pack(anchor="w", pady=(0, 4))\n        self._crear_tabla_rangos(col_hum, HUM_PARAMS)\n\n    def _crear_tabla_rangos(self, parent, params_dict):\n        columnas = ("etiqueta", "completo", "seguro")\n        tree = ttk.Treeview(parent, columns=columnas, show="headings", height=len(params_dict))\n        tree.heading("etiqueta", text="Etiqueta")\n        tree.heading("completo", text="Rango completo (a–d)")\n        tree.heading("seguro", text="100% segura (b–c)")\n        tree.column("etiqueta", width=90, anchor="center")\n        tree.column("completo", width=140, anchor="center")\n        tree.column("seguro", width=140, anchor="center")\n\n        for nombre, (a, b, c, d) in params_dict.items():\n            rango_completo = f"{a} – {d}"\n            rango_seguro = f"{b} – {c}" if b != c else f"{b}"\n            tree.insert("", "end", values=(nombre, rango_completo, rango_seguro))\n\n        tree.pack(fill="x")\n\n        for nombre, (a, b, c, d) in params_dict.items():\n            texto = f"• {nombre}: {describir_rango(a, b, c, d)}"\n            tk.Label(parent, text=texto, bg=COLOR_PANEL, fg=COLOR_MUTED,\n                     font=(FONT_FAMILY, 8), wraplength=380, justify="left").pack(anchor="w", pady=(2, 0))\n\n    def _embeber_grafica(self, frame, variable):\n        for widget in frame.winfo_children():\n            widget.destroy()\n\n        variable.view(sim=self.sim)\n        fig = plt.gcf()\n        fig.set_size_inches(7.6, 2.3)\n        fig.tight_layout()\n\n        canvas = FigureCanvasTkAgg(fig, master=frame)\n        canvas.draw()\n        canvas.get_tk_widget().pack(fill="both", expand=True)\n\n        plt.close(fig)\n        return canvas\n\n    def calcular(self):\n        try:\n            t = float(self.var_temp.get())\n            h = float(self.var_hum.get())\n        except ValueError:\n            messagebox.showerror("Valor inválido", "Temperatura y humedad deben ser números.")\n            return\n\n        if not (0 <= t <= 40):\n            messagebox.showwarning("Fuera de rango", "La temperatura debería estar entre 0 y 40 °C.")\n        if not (0 <= h <= 100):\n            messagebox.showwarning("Fuera de rango", "La humedad debería estar entre 0 y 100 %.")\n\n        self.lbl_estado.config(text="Calculando inferencia difusa con skfuzzy…")\n        self.root.update_idletasks()\n\n        self.sim.input["temperatura"] = t\n        self.sim.input["humedad_suelo"] = h\n\n        try:\n            self.sim.compute()\n        except Exception as err:\n            self.lbl_resultado.config(text="Tiempo de riego: sin activación")\n            self.lbl_estado.config(text="Ninguna regla se activó con estos valores.")\n            messagebox.showwarning(\n                "Sin activación",\n                f"El motor difuso no encontró reglas aplicables para T={t} y H={h}.\\n\\nError técnico: {err}",\n            )\n            return\n\n        resultado = self.sim.output["tiempo_riego"]\n        self.lbl_resultado.config(text=f"Tiempo estimado de riego: {resultado:.2f} minutos")\n\n        self._embeber_grafica(self.frame_temp, self.temperatura)\n        self._embeber_grafica(self.frame_hum, self.humedad)\n        self._embeber_grafica(self.frame_riego, self.riego)\n\n        self.lbl_estado.config(text="Cálculo completado exitosamente.")\n\n    def guardar_graficas(self):\n        try:\n            t = float(self.var_temp.get())\n            h = float(self.var_hum.get())\n        except ValueError:\n            messagebox.showerror("Valor inválido", "Calcula primero con valores válidos.")\n            return\n\n        self.sim.input["temperatura"] = t\n        self.sim.input["humedad_suelo"] = h\n        try:\n            self.sim.compute()\n        except Exception as err:\n            messagebox.showwarning("Sin activación", f"No se puede graficar: {err}")\n            return\n\n        nombres = {\n            self.temperatura: "invernadero_temperatura.png",\n            self.humedad: "invernadero_humedad.png",\n            self.riego: "invernadero_riego.png",\n        }\n        rutas_guardadas = []\n        for variable, nombre_archivo in nombres.items():\n            variable.view(sim=self.sim)\n            fig = plt.gcf()\n            ruta = self.carpeta_script / nombre_archivo\n            fig.savefig(ruta, dpi=150, bbox_inches="tight")\n            plt.close(fig)\n            rutas_guardadas.append(str(ruta))\n\n        messagebox.showinfo(\n            "Gráficas guardadas",\n            "Se generaron las gráficas como PNG en la misma carpeta del script:\\n\\n" + "\\n".join(rutas_guardadas),\n        )\n        self.lbl_estado.config(text="Gráficas guardadas correctamente.")\n'
EXPERT_SOURCE = '#!/usr/bin/env python3\n# -*- coding: utf-8 -*-\n\nimport sys\nimport tkinter as tk\nfrom tkinter import ttk, messagebox\n\ntry:\n    import clips # type: ignore\nexcept ImportError as _err:\n    clips = None\n    CLIPSPY_IMPORT_ERROR = _err\n\n# ==============================================================================\n#  [1] CONSTRUCTOS CLIPS\n# ==============================================================================\n# plantillas y reglas de diagnóstico.\n\nTEMPLATE_FASE = """(deftemplate fase\n   (slot actual (type SYMBOL) (allowed-values inicio preguntas inferencia resultado fin)))"""\n\nTEMPLATE_SINTOMA = """(deftemplate sintoma\n   (slot cultivo (type SYMBOL) (allowed-values tomate pimiento pepino lechuga fresa ornamental otro))\n   (slot organo (type SYMBOL) (allowed-values hojas fruto flores tallo-cuello raices))\n   (slot apariencia (type SYMBOL) (allowed-values moho-gris polvo-blanco manchas-angulares manchas-plateadas melaza-hoja-arrugada cuello-podrido mancha-negra-fruto nodulos-agallas ninguno))\n   (slot plaga-visible (type SYMBOL) (allowed-values mosquitas-blancas pulgones bichitos-diminutos ninguno))\n   (slot microclima (type SYMBOL) (allowed-values alta-humedad-cerrado templado-seco normal)))"""\n\nTEMPLATE_DIAGNOSTICO = """(deftemplate diagnostico\n   (slot nombre-patologia (type STRING))\n   (slot tipo-agente (type SYMBOL) (allowed-values hongo insecto-plaga nematodo desorden-abiotico desconocido))\n   (slot severidad (type SYMBOL) (allowed-values baja media alta critica))\n   (slot control-invernadero (type STRING)))"""\n\nREGLA_BOTRYTIS = """(defrule regla-botrytis\n   (fase (actual inferencia))\n   (sintoma (organo flores | fruto | hojas | tallo-cuello) (apariencia moho-gris))\n   =>\n   (assert (diagnostico\n      (nombre-patologia "Moho Gris / Podredumbre Gris (Botrytis cinerea)")\n      (tipo-agente hongo)\n      (severidad critica)\n      (control-invernadero "URGENTE: Abrir ventilaciones laterales/cenitales para bajar humedad <75%. Retirar partes con bolsa plastica para evitar esporas. Aplicar fungicidas especificos (Iprodiona, Cyprodinil o Bacillus subtilis)."))))"""\n\nREGLA_MOSCA_BLANCA = """(defrule regla-mosca-blanca\n   (fase (actual inferencia))\n   (sintoma (plaga-visible mosquitas-blancas))\n   =>\n   (assert (diagnostico\n      (nombre-patologia "Infestacion por Mosca Blanca (Bemisia tabaci / Trialeurodes)")\n      (tipo-agente insecto-plaga)\n      (severidad alta)\n      (control-invernadero "Instalar trampas cromaticas adhesivas amarillas. Realizar suelta de parasitoides (Encarsia formosa) o aplicar jabon potasico + extracto de neem al atardecer."))))"""\n\nREGLA_OIDIO = """(defrule regla-oidio\n   (fase (actual inferencia))\n   (sintoma (organo hojas) (apariencia polvo-blanco))\n   =>\n   (assert (diagnostico\n      (nombre-patologia "Oidio / Ceniza blanca (Erysiphe / Leveillula taurica)")\n      (tipo-agente hongo)\n      (severidad media)\n      (control-invernadero "Aumentar separacion de plantas para permitir paso de luz. Aplicar azufre por sublimacion/pulverizacion o bicarbonato potasico. Evitar estres termico."))))"""\n\nREGLA_TRIPS = """(defrule regla-trips\n   (fase (actual inferencia))\n   (sintoma (apariencia manchas-plateadas) (plaga-visible bichitos-diminutos | ninguno))\n   =>\n   (assert (diagnostico\n      (nombre-patologia "Ataque de Trips (Frankliniella occidentalis)")\n      (tipo-agente insecto-plaga)\n      (severidad alta)\n      (control-invernadero "Colocar placas adhesivas azules a la altura del dosel. Introducir acaros depredadores (Amblyseius swirskii / Orius laevigatus) y monitorear transmision de virus."))))"""\n\nREGLA_MILDIU = """(defrule regla-mildiu\n   (fase (actual inferencia))\n   (sintoma (organo hojas) (apariencia manchas-angulares) (microclima alta-humedad-cerrado))\n   =>\n   (assert (diagnostico\n      (nombre-patologia "Mildiu Velloso (Pseudoperonospora / Bremia lactucae)")\n      (tipo-agente hongo)\n      (severidad alta)\n      (control-invernadero "Evitar condensacion en el techo del plastico. Suspender riego por aspersion; regar solo por goteo matutino. Aplicar fungicidas sistemicos (Metalaxil o Fosetil-Al)."))))"""\n\nREGLA_PULGONES = """(defrule regla-pulgones\n   (fase (actual inferencia))\n   (sintoma (apariencia melaza-hoja-arrugada) (plaga-visible pulgones))\n   =>\n   (assert (diagnostico\n      (nombre-patologia "Ataque severo de Pulgon / Afidos (Aphis gossypii / Myzus persicae)")\n      (tipo-agente insecto-plaga)\n      (severidad media)\n      (control-invernadero "Lavado foliar con jabon potasico para retirar melaza y evitar hongo negrilla. Liberar mariquitas (Coccinelidos) o avispillas (Aphidius colemani)."))))"""\n\nREGLA_DAMPING_OFF = """(defrule regla-damping-off\n   (fase (actual inferencia))\n   (sintoma (organo tallo-cuello) (apariencia cuello-podrido))\n   =>\n   (assert (diagnostico\n      (nombre-patologia "Damping-off o Caida de Plantulas (Pythium / Rhizoctonia)")\n      (tipo-agente hongo)\n      (severidad critica)\n      (control-invernadero "Desinfectar sustratos y bandejas de siembra con vapor o agua oxigenada. Reducir frecuencia de riego en semillero e inocular con Trichoderma harzianum."))))"""\n\nREGLA_PODREDUMBRE_APICAL = """(defrule regla-podredumbre-apical\n   (fase (actual inferencia))\n   (sintoma (cultivo tomate | pimiento) (organo fruto) (apariencia mancha-negra-fruto))\n   =>\n   (assert (diagnostico\n      (nombre-patologia "Podredumbre Apical / Blossom End Rot (Deficiencia de Calcio / Riego irregular)")\n      (tipo-agente desorden-abiotico)\n      (severidad media)\n      (control-invernadero "No es un patogeno contagioso. Homogeneizar los pulsos de fertirriego (evitar que el sustrato se seque) y aplicar aporte foliar de Nitrato o Quelato de Calcio."))))"""\n\nREGLA_NEMATODOS = """(defrule regla-nematodos\n   (fase (actual inferencia))\n   (sintoma (organo raices) (apariencia nodulos-agallas))\n   =>\n   (assert (diagnostico\n      (nombre-patologia "Nematodos Fitoparasitos Agalladores (Meloidogyne spp.)")\n      (tipo-agente nematodo)\n      (severidad alta)\n      (control-invernadero "Solarizacion del suelo en verano entre ciclos. Incorporar materia organica biofumigante (mostaza/col) y aplicar nematicidas biologicos (Paecilomyces lilacinus)."))))"""\n\nREGLA_SIN_COINCIDENCIA = """(defrule regla-sin-coincidencia\n   (declare (salience -5))\n   (fase (actual inferencia))\n   (not (diagnostico))\n   =>\n   (assert (diagnostico\n      (nombre-patologia "Patologia o anomalia no catalogada con el patron ingresado")\n      (tipo-agente desconocido)\n      (severidad baja)\n      (control-invernadero "Aislar la planta afectada preventivamente y enviar muestra a laboratorio fitosanitario para analisis bacteriologico/virologico."))))"""\n\nREGLA_PASAR_A_RESULTADO = """(defrule pasar-a-resultado\n   (declare (salience -10))\n   ?f <- (fase (actual inferencia))\n   =>\n   (modify ?f (actual resultado)))"""\n\nCLIPS_LOGIC = [\n    TEMPLATE_FASE, TEMPLATE_SINTOMA, TEMPLATE_DIAGNOSTICO,\n    REGLA_BOTRYTIS, REGLA_MOSCA_BLANCA, REGLA_OIDIO, REGLA_TRIPS,\n    REGLA_MILDIU, REGLA_PULGONES, REGLA_DAMPING_OFF, REGLA_PODREDUMBRE_APICAL,\n    REGLA_NEMATODOS, REGLA_SIN_COINCIDENCIA, REGLA_PASAR_A_RESULTADO\n]\n\n\n# ==============================================================================\n#  [2] INTERFAZ GRÁFICA (PYTHON + TKINTER)\n# ==============================================================================\n\n# Paleta de colores corporativa (tema "invernadero")\nCOLOR_BG = "#F3F6F3"            # fondo general\nCOLOR_PANEL = "#FFFFFF"         # fondo de tarjetas/paneles\nCOLOR_PRIMARY = "#1F6D3D"       # verde principal (marca)\nCOLOR_PRIMARY_DARK = "#164F2C"  # verde oscuro (hover)\nCOLOR_ACCENT = "#2E9E5B"        # verde acento\nCOLOR_TEXT = "#1E2A22"          # texto principal\nCOLOR_MUTED = "#5B6B60"         # texto secundario\nCOLOR_BORDER = "#DCE5DD"        # bordes suaves\n\nSEVERIDAD_COLORES = {\n    "baja": ("#2E7D32", "#E8F5E9"),\n    "media": ("#B8860B", "#FFF8E1"),\n    "alta": ("#D2691E", "#FFF1E6"),\n    "critica": ("#C62828", "#FDECEA"),\n}\n\nFONT_FAMILY = "Segoe UI"\n\n\nclass InvernaderoGUI:\n    def __init__(self, root, on_back=None):\n        self.root = root\n        self.on_back = on_back\n        self.root.title("Sistema Experto · Fitosanidad de Invernaderos")\n        self.root.geometry("780x760")\n        self.root.minsize(680, 640)\n        self.root.configure(bg=COLOR_BG)\n\n        self._configurar_estilos()\n        self._construir_layout()\n\n    # --------------------------------------------------------------------\n    #  Estilos ttk\n    # --------------------------------------------------------------------\n    def _configurar_estilos(self):\n        style = ttk.Style(self.root)\n        if "clam" in style.theme_names():\n            style.theme_use("clam")\n\n        style.configure("App.TFrame", background=COLOR_BG)\n        style.configure("Header.TFrame", background=COLOR_PRIMARY)\n        style.configure("Card.TFrame", background=COLOR_PANEL)\n\n        style.configure(\n            "Header.TLabel",\n            background=COLOR_PRIMARY,\n            foreground="#FFFFFF",\n            font=(FONT_FAMILY, 18, "bold"),\n        )\n        style.configure(\n            "SubHeader.TLabel",\n            background=COLOR_PRIMARY,\n            foreground="#DDEFE2",\n            font=(FONT_FAMILY, 10),\n        )\n        style.configure(\n            "SectionTitle.TLabel",\n            background=COLOR_PANEL,\n            foreground=COLOR_PRIMARY_DARK,\n            font=(FONT_FAMILY, 12, "bold"),\n        )\n        style.configure(\n            "FieldLabel.TLabel",\n            background=COLOR_PANEL,\n            foreground=COLOR_TEXT,\n            font=(FONT_FAMILY, 10, "bold"),\n        )\n        style.configure(\n            "Hint.TLabel",\n            background=COLOR_PANEL,\n            foreground=COLOR_MUTED,\n            font=(FONT_FAMILY, 8),\n        )\n        style.configure(\n            "Status.TLabel",\n            background=COLOR_BG,\n            foreground=COLOR_MUTED,\n            font=(FONT_FAMILY, 9),\n        )\n\n        style.configure(\n            "TCombobox",\n            fieldbackground="#FFFFFF",\n            background="#FFFFFF",\n            foreground=COLOR_TEXT,\n            arrowcolor=COLOR_PRIMARY_DARK,\n            padding=6,\n        )\n        style.map(\n            "TCombobox",\n            fieldbackground=[("readonly", "#FFFFFF")],\n            bordercolor=[("focus", COLOR_ACCENT)],\n        )\n\n        style.configure(\n            "Accent.TButton",\n            background=COLOR_PRIMARY,\n            foreground="#FFFFFF",\n            font=(FONT_FAMILY, 11, "bold"),\n            padding=(18, 10),\n            borderwidth=0,\n        )\n        style.map(\n            "Accent.TButton",\n            background=[("active", COLOR_PRIMARY_DARK), ("pressed", COLOR_PRIMARY_DARK)],\n        )\n\n    # --------------------------------------------------------------------\n    #  Construcción del layout\n    # --------------------------------------------------------------------\n    def _construir_layout(self):\n        # ---------- Encabezado ----------\n        header = ttk.Frame(self.root, style="Header.TFrame", padding=(24, 18))\n        header.pack(fill="x")\n\n        ttk.Label(header, text="🌱  Diagnóstico Fitosanitario de Invernadero", style="Header.TLabel").pack(anchor="w")\n        ttk.Label(\n            header,\n            text="Sistema experto basado en CLIPS para el manejo integrado de plagas y enfermedades",\n            style="SubHeader.TLabel",\n        ).pack(anchor="w", pady=(4, 0))\n\n        # ---------- Cuerpo ----------\n        body = ttk.Frame(self.root, style="App.TFrame", padding=(24, 18))\n        body.pack(fill="both", expand=True)\n        body.columnconfigure(0, weight=1)\n        body.rowconfigure(1, weight=1)\n\n        # ----- Tarjeta de entradas -----\n        card_inputs = tk.Frame(body, bg=COLOR_PANEL, highlightbackground=COLOR_BORDER, highlightthickness=1)\n        card_inputs.grid(row=0, column=0, sticky="ew", pady=(0, 16))\n\n        inner_inputs = ttk.Frame(card_inputs, style="Card.TFrame", padding=(20, 16))\n        inner_inputs.pack(fill="both", expand=True)\n        inner_inputs.columnconfigure(1, weight=1)\n\n        ttk.Label(inner_inputs, text="Observaciones del cultivo", style="SectionTitle.TLabel").grid(\n            row=0, column=0, columnspan=2, sticky="w", pady=(0, 2)\n        )\n        ttk.Label(\n            inner_inputs,\n            text="Seleccione una opción para cada categoría según lo observado en planta.",\n            style="Hint.TLabel",\n        ).grid(row=1, column=0, columnspan=2, sticky="w", pady=(0, 12))\n\n        # Configuraciones de las opciones (IDÉNTICAS a los allowed-values en CLIPS)\n        self.opciones = {\n            "🌾  Cultivo": ["tomate", "pimiento", "pepino", "lechuga", "fresa", "ornamental", "otro"],\n            "🍃  Órgano principal": ["hojas", "fruto", "flores", "tallo-cuello", "raices"],\n            "🔎  Apariencia / lesión": ["moho-gris", "polvo-blanco", "manchas-angulares", "manchas-plateadas", "melaza-hoja-arrugada", "cuello-podrido", "mancha-negra-fruto", "nodulos-agallas", "ninguno"],\n            "🐛  Plaga visible": ["mosquitas-blancas", "pulgones", "bichitos-diminutos", "ninguno"],\n            "🌡️  Microclima": ["alta-humedad-cerrado", "templado-seco", "normal"],\n        }\n\n        self.comboboxes = {}\n\n        fila = 2\n        for etiqueta, valores in self.opciones.items():\n            ttk.Label(inner_inputs, text=etiqueta, style="FieldLabel.TLabel").grid(\n                row=fila, column=0, sticky="w", pady=8, padx=(0, 12)\n            )\n            cb = ttk.Combobox(inner_inputs, values=valores, state="readonly", font=(FONT_FAMILY, 10))\n            cb.grid(row=fila, column=1, sticky="ew", pady=8)\n            cb.set("")\n            self.comboboxes[etiqueta] = cb\n            fila += 1\n\n        # Botón de acción\n        btn_bar = ttk.Frame(inner_inputs, style="Card.TFrame")\n        btn_bar.grid(row=fila, column=0, columnspan=2, sticky="e", pady=(14, 0))\n\n        self.btn_diagnosticar = ttk.Button(\n            btn_bar, text="🔬  Generar diagnóstico", style="Accent.TButton", command=self.ejecutar_diagnostico\n        )\n        self.btn_diagnosticar.pack(side="right")\n\n        ttk.Button(btn_bar, text="Limpiar", command=self._limpiar_formulario).pack(side="right", padx=(0, 10))\n        ttk.Button(btn_bar, text="🔄 Reiniciar / volver al inicio", command=self.on_back).pack(side="right", padx=(0, 10))\n\n        # ----- Tarjeta de resultados -----\n        card_resultado = tk.Frame(body, bg=COLOR_PANEL, highlightbackground=COLOR_BORDER, highlightthickness=1)\n        card_resultado.grid(row=1, column=0, sticky="nsew")\n\n        inner_resultado = ttk.Frame(card_resultado, style="Card.TFrame", padding=(20, 16))\n        inner_resultado.pack(fill="both", expand=True)\n        inner_resultado.columnconfigure(0, weight=1)\n        inner_resultado.rowconfigure(2, weight=1)\n\n        ttk.Label(inner_resultado, text="Dictamen técnico fitosanitario", style="SectionTitle.TLabel").grid(\n            row=0, column=0, sticky="w"\n        )\n\n        # Insignia de severidad (se actualiza dinámicamente)\n        self.badge_severidad = tk.Label(\n            inner_resultado,\n            text="Sin diagnóstico",\n            font=(FONT_FAMILY, 9, "bold"),\n            fg=COLOR_MUTED,\n            bg="#EEF2EF",\n            padx=10,\n            pady=3,\n        )\n        self.badge_severidad.grid(row=1, column=0, sticky="w", pady=(6, 12))\n\n        text_frame = tk.Frame(inner_resultado, bg=COLOR_PANEL)\n        text_frame.grid(row=2, column=0, sticky="nsew")\n        text_frame.columnconfigure(0, weight=1)\n        text_frame.rowconfigure(0, weight=1)\n\n        self.lbl_resultado_texto = tk.Text(\n            text_frame,\n            wrap="word",\n            font=(FONT_FAMILY, 11),\n            bg="#FBFDFB",\n            fg=COLOR_TEXT,\n            relief="flat",\n            padx=14,\n            pady=12,\n            state="disabled",\n            spacing3=6,\n        )\n        self.lbl_resultado_texto.grid(row=0, column=0, sticky="nsew")\n\n        scrollbar = ttk.Scrollbar(text_frame, orient="vertical", command=self.lbl_resultado_texto.yview)\n        scrollbar.grid(row=0, column=1, sticky="ns")\n        self.lbl_resultado_texto.configure(yscrollcommand=scrollbar.set)\n\n        # Estilos de texto (tags) para el informe\n        self.lbl_resultado_texto.tag_configure(\n            "titulo", font=(FONT_FAMILY, 10, "bold"), foreground=COLOR_PRIMARY_DARK, spacing1=8\n        )\n        self.lbl_resultado_texto.tag_configure("valor", font=(FONT_FAMILY, 11), foreground=COLOR_TEXT)\n        self.lbl_resultado_texto.tag_configure(\n            "placeholder", font=(FONT_FAMILY, 10, "italic"), foreground=COLOR_MUTED\n        )\n        self._mostrar_placeholder()\n\n        # ---------- Barra de estado ----------\n        footer = ttk.Frame(self.root, style="App.TFrame", padding=(24, 0, 24, 12))\n        footer.pack(fill="x")\n        self.lbl_estado = ttk.Label(footer, text="Listo para diagnosticar.", style="Status.TLabel")\n        self.lbl_estado.pack(anchor="w")\n\n    # --------------------------------------------------------------------\n    #  Utilidades de interfaz\n    # --------------------------------------------------------------------\n    def _mostrar_placeholder(self):\n        self.lbl_resultado_texto.config(state="normal")\n        self.lbl_resultado_texto.delete("1.0", tk.END)\n        self.lbl_resultado_texto.insert(\n            tk.END,\n            "Complete el formulario y presione «Generar diagnóstico» para ver aquí el "\n            "dictamen técnico y el protocolo de manejo recomendado.",\n            "placeholder",\n        )\n        self.lbl_resultado_texto.config(state="disabled")\n\n    def _limpiar_formulario(self):\n        for cb in self.comboboxes.values():\n            cb.set("")\n        self._mostrar_placeholder()\n        self.badge_severidad.config(text="Sin diagnóstico", fg=COLOR_MUTED, bg="#EEF2EF")\n        self.lbl_estado.config(text="Formulario limpiado.")\n\n    def _actualizar_badge(self, severidad):\n        color_fg, color_bg = SEVERIDAD_COLORES.get(severidad, (COLOR_MUTED, "#EEF2EF"))\n        self.badge_severidad.config(\n            text=f"Severidad: {severidad.upper()}", fg=color_fg, bg=color_bg\n        )\n\n    def _renderizar_informe(self, cultivo, diagnostico):\n        self.lbl_resultado_texto.config(state="normal")\n        self.lbl_resultado_texto.delete("1.0", tk.END)\n\n        secciones = [\n            ("CULTIVO ANALIZADO", cultivo.upper()),\n            ("PROBLEMA DIAGNOSTICADO", diagnostico["patologia"]),\n            ("TIPO DE PATÓGENO / CAUSA", str(diagnostico["agente"]).upper()),\n            ("NIVEL DE SEVERIDAD", str(diagnostico["severidad"]).upper()),\n            ("PROTOCOLO DE MANEJO INTEGRADO", diagnostico["control"]),\n        ]\n\n        for i, (titulo, valor) in enumerate(secciones):\n            self.lbl_resultado_texto.insert(tk.END, f"{titulo}\\n", "titulo")\n            self.lbl_resultado_texto.insert(tk.END, f"{valor}\\n", "valor")\n            if i < len(secciones) - 1:\n                self.lbl_resultado_texto.insert(tk.END, "\\n")\n\n        self.lbl_resultado_texto.config(state="disabled")\n\n    # --------------------------------------------------------------------\n    #  Lógica de diagnóstico (sin cambios respecto al motor CLIPS)\n    # --------------------------------------------------------------------\n    def ejecutar_diagnostico(self):\n        # 1. Obtener valores de la interfaz\n        valores_seleccionados = [cb.get() for cb in self.comboboxes.values()]\n\n        # Validar que todos tengan algo seleccionado\n        if "" in valores_seleccionados:\n            messagebox.showwarning("Campos incompletos", "Por favor, selecciona una opción para cada categoría.")\n            return\n\n        cultivo, organo, apariencia, plaga, microclima = valores_seleccionados\n        self.lbl_estado.config(text="Ejecutando motor de inferencia CLIPS…")\n        self.root.update_idletasks()\n\n        # 2. Inicializar Motor CLIPS\n        if clips is None:\n            messagebox.showerror(\n                "Dependencia faltante",\n                "No se encontró CLIPSPY. Instálalo con:\\n\\npip install clipspy"\n            )\n            self.lbl_estado.config(text="Falta la librería CLIPSPY.")\n            return\n\n        env = clips.Environment()\n        for constructo in CLIPS_LOGIC:\n            try:\n                env.build(constructo)\n            except clips.CLIPSError as error:\n                messagebox.showerror("Error CLIPS", f"Fallo al compilar lógica:\\n{error}")\n                self.lbl_estado.config(text="Error al compilar la base de conocimiento.")\n                return\n\n        env.reset()\n\n        # 3. Inyectar los hechos directamente al motor (Reemplaza las preguntas por consola)\n        hecho_sintoma = f"(sintoma (cultivo {cultivo}) (organo {organo}) (apariencia {apariencia}) (plaga-visible {plaga}) (microclima {microclima}))"\n        env.assert_string(hecho_sintoma)\n        env.assert_string("(fase (actual inferencia))")\n\n        # 4. Ejecutar el razonamiento\n        env.run()\n\n        # 5. Extraer y mostrar resultados\n        diagnostico_final = None\n        for fact in env.facts():\n            if fact.template.name == "diagnostico":\n                diagnostico_final = {\n                    "patologia": fact["nombre-patologia"],\n                    "agente": fact["tipo-agente"],\n                    "severidad": fact["severidad"],\n                    "control": fact["control-invernadero"]\n                }\n                break\n\n        if diagnostico_final:\n            self._renderizar_informe(cultivo, diagnostico_final)\n            self._actualizar_badge(str(diagnostico_final["severidad"]))\n            self.lbl_estado.config(text="Diagnóstico generado correctamente.")\n        else:\n            self.lbl_estado.config(text="El motor no produjo un diagnóstico.")\n'


